import {
  formatExpectedOneArgument,
  formatHelp,
  formatRequiredError,
  formatUnrecognizedArguments,
} from './text.mjs';

const OPTION_ORDER = ['a', 'b', 'c', 'd'];
const OPTION_MAP = new Map(OPTION_ORDER.map((key) => [`--${key}`, key]));
const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$|^-\.\d+$/;

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test10.mjs';
  }

  const parts = scriptPath.split(/[\\/]/);
  return parts[parts.length - 1] || scriptPath;
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function isOptionLike(token) {
  return typeof token === 'string' && token.startsWith('-');
}

function splitLongOption(token) {
  if (!token.startsWith('--')) {
    return null;
  }

  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return {
      optionToken: token,
      hasInlineValue: false,
      inlineValue: '',
    };
  }

  return {
    optionToken: token.slice(0, equalsIndex),
    hasInlineValue: true,
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function shouldConsumeUnknownOptionValue(nextToken) {
  if (nextToken === undefined || nextToken === '--') {
    return false;
  }

  if (!isOptionLike(nextToken)) {
    return true;
  }

  return isNegativeNumberLike(nextToken);
}

export function parseCommandLine(argv, programName) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
    d: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        text: formatHelp(programName),
      };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const longOption = splitLongOption(token);
      const key = OPTION_MAP.get(longOption.optionToken);

      if (!key) {
        extras.push(token);
        if (!longOption.hasInlineValue && shouldConsumeUnknownOptionValue(argv[index + 1])) {
          index += 1;
          extras.push(argv[index]);
        }
        continue;
      }

      if (longOption.hasInlineValue) {
        values[key] = longOption.inlineValue;
        continue;
      }

      const nextToken = argv[index + 1];
      if (nextToken === undefined || (isOptionLike(nextToken) && !isNegativeNumberLike(nextToken))) {
        return {
          kind: 'error',
          code: 2,
          text: formatExpectedOneArgument(programName, longOption.optionToken),
        };
      }

      index += 1;
      values[key] = argv[index];
      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_ORDER.filter((key) => values[key] === undefined).map((key) => `--${key}`);
  if (missing.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: formatRequiredError(programName, missing),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: formatUnrecognizedArguments(programName, extras),
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D\n`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n  --d D\n`;
}

export function formatRequiredError(programName, missingOptions) {
  return `${formatUsage(programName)}${programName}: error: the following arguments are required: ${missingOptions.join(', ')}\n`;
}

export function formatExpectedOneArgument(programName, optionName) {
  return `${formatUsage(programName)}${programName}: error: argument ${optionName}: expected one argument\n`;
}

export function formatUnrecognizedArguments(programName, extras) {
  return `${formatUsage(programName)}${programName}: error: unrecognized arguments: ${extras.join(' ')}\n`;
}

export function formatUnhandledScheduleError(error) {
  const traceLine = Number.isInteger(error.traceLine) ? error.traceLine : 514;

  return `Traceback (most recent call last):\n  File "test10.py", line 21, in <module>\n  File "schedule/__init__.py", line ${traceLine}, in at\nschedule.ScheduleValueError: ${error.message}\n[PYI-${process.pid}:ERROR] Failed to execute script 'test10' due to unhandled exception!\n`;
}

import { getProgramName, parseCommandLine } from './lib/cli/parser.mjs';
import {
  ScheduleValueError,
  cancel_job,
  clear,
  every,
  get_jobs,
} from './lib/schedule/index.mjs';
import { formatUnhandledScheduleError } from './lib/runtime/python-traceback.mjs';

function writeLine(value) {
  process.stdout.write(`${String(value)}\n`);
}

function run(values) {
  const job1 = every().seconds.do(() => null);
  writeLine(job1);
  cancel_job(job1);
  writeLine(get_jobs().length);

  const job2 = every().minutes.do(() => null);
  writeLine(job2);
  const job3 = every().hours.do(() => null);
  writeLine(job3);

  clear();
  writeLine(get_jobs().length);

  const job4 = every().days.at(values.a).do(() => null);
  writeLine(job4);
  const job5 = every().weeks.do(() => null);
  writeLine(job5);
  writeLine(get_jobs().length);
}

const programName = getProgramName(process.argv[1]);
const parsed = parseCommandLine(process.argv.slice(2), programName);

if (parsed.kind === 'help') {
  process.stdout.write(parsed.text);
} else if (parsed.kind === 'error') {
  process.stderr.write(parsed.text);
  process.exitCode = parsed.code;
} else {
  try {
    run(parsed.values);
  } catch (error) {
    if (error instanceof ScheduleValueError) {
      process.stderr.write(formatUnhandledScheduleError(error));
      process.exitCode = 1;
    } else {
      throw error;
    }
  }
}

const OPTION_ORDER = ["a", "b", "c", "d"];

const OPTION_MAP = new Map(
  OPTION_ORDER.map((name) => [`--${name}`, name]),
);

function basename(pathText) {
  if (!pathText) {
    return "test10.mjs";
  }

  const normalized = String(pathText).replace(/\\/g, "/");
  const segments = normalized.split("/");
  return segments[segments.length - 1] || "test10.mjs";
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n  --d D\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

function splitInlineOption(token) {
  const separatorIndex = token.indexOf("=");

  if (separatorIndex === -1) {
    return null;
  }

  return {
    optionToken: token.slice(0, separatorIndex),
    value: token.slice(separatorIndex + 1),
  };
}

export class CliExit extends Error {
  constructor(exitCode, stdoutText = "", stderrText = "") {
    super("CLI requested exit");
    this.name = "CliExit";
    this.exitCode = exitCode;
    this.stdoutText = stdoutText;
    this.stderrText = stderrText;
  }
}

export function parseTest10Args(argv) {
  const programName = basename(argv[1]);
  const tokens = argv.slice(2);

  const values = new Map();
  const extras = [];
  let endOfOptions = false;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (endOfOptions) {
      extras.push(token);
      continue;
    }

    if (token === "--") {
      endOfOptions = true;
      continue;
    }

    if (token === "-h" || token === "--help") {
      throw new CliExit(0, formatHelp(programName));
    }

    const inlineOption = splitInlineOption(token);
    if (inlineOption !== null) {
      const optionName = OPTION_MAP.get(inlineOption.optionToken);

      if (optionName === undefined) {
        extras.push(token);
        continue;
      }

      values.set(optionName, inlineOption.value);
      continue;
    }

    const optionName = OPTION_MAP.get(token);
    if (optionName !== undefined) {
      const nextToken = tokens[index + 1];

      if (
        nextToken === undefined ||
        nextToken === "--" ||
        OPTION_MAP.has(nextToken) ||
        nextToken === "-h" ||
        nextToken === "--help"
      ) {
        throw new CliExit(
          2,
          "",
          formatError(programName, `argument ${token}: expected one argument`),
        );
      }

      values.set(optionName, nextToken);
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_ORDER.filter((name) => !values.has(name));
  if (missing.length > 0) {
    const message = `the following arguments are required: ${missing.map((name) => `--${name}`).join(", ")}`;
    throw new CliExit(2, "", formatError(programName, message));
  }

  if (extras.length > 0) {
    throw new CliExit(
      2,
      "",
      formatError(programName, `unrecognized arguments: ${extras.join(" ")}`),
    );
  }

  return {
    a: values.get("a"),
    b: values.get("b"),
    c: values.get("c"),
    d: values.get("d"),
  };
}

export { formatHelp, formatUsage };

const TEST10_SOURCE_LINE = 21;

export class OutputBuffer {
  constructor() {
    this.stdoutChunks = [];
  }

  log(value) {
    this.stdoutChunks.push(`${String(value)}\n`);
  }

  flushStdout() {
    if (this.stdoutChunks.length === 0) {
      return;
    }

    process.stdout.write(this.stdoutChunks.join(""));
    this.stdoutChunks = [];
  }
}

export function formatUnhandledScheduleError(error) {
  return `Traceback (most recent call last):\n  File "test10.py", line ${TEST10_SOURCE_LINE}, in <module>\n  File "schedule/__init__.py", line ${error.sourceLine}, in at\nschedule.ScheduleValueError: ${error.message}\n[PYI-${process.pid}:ERROR] Failed to execute script 'test10' due to unhandled exception!\n`;
}

import { Scheduler } from './scheduler.mjs';

const defaultScheduler = new Scheduler();

export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

export function cancel_job(job) {
  defaultScheduler.cancelJob(job);
}

export function get_jobs() {
  return defaultScheduler.getJobs();
}

export function clear() {
  defaultScheduler.clear();
}

export { ScheduleValueError } from './errors.mjs';

import { ScheduleValueError } from './errors.mjs';
import { validateDailyAtTime } from './validation.mjs';

function formatCallableName(jobFunction) {
  return jobFunction.name || '<lambda>';
}

export class Job {
  constructor(interval, scheduler) {
    this.interval = interval;
    this.scheduler = scheduler;
    this.unit = null;
    this.jobFunction = null;
    this.jobName = null;
    this.jobArgs = [];
    this.atTime = null;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  at(timeText) {
    if (this.unit !== 'days') {
      throw new ScheduleValueError('Invalid time format for a daily job (valid format is HH:MM(:SS)?)');
    }

    this.atTime = validateDailyAtTime(timeText);
    return this;
  }

  do(jobFunction, ...jobArgs) {
    this.jobFunction = jobFunction;
    this.jobName = formatCallableName(jobFunction);
    this.jobArgs = jobArgs;
    this.scheduler.addJob(this);
    return this;
  }

  toString() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=${this.jobName}, args=(), kwargs={})`;
  }
}

export class ScheduleValueError extends Error {
  constructor(message, traceLine = 514) {
    super(message);
    this.name = 'ScheduleValueError';
    this.traceLine = traceLine;
  }
}

import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    return new Job(interval, this);
  }

  addJob(job) {
    this.jobs.push(job);
  }

  cancelJob(job) {
    this.jobs = this.jobs.filter((candidate) => candidate !== job);
  }

  getJobs() {
    return this.jobs.slice();
  }

  clear() {
    this.jobs = [];
  }
}

import { ScheduleValueError } from './errors.mjs';

const DAILY_TIME_PATTERN = /^[0-2]\d:[0-5]\d(?::[0-5]\d)?$/;

export function validateDailyAtTime(timeText) {
  const normalized = String(timeText);

  if (!DAILY_TIME_PATTERN.test(normalized)) {
    throw new ScheduleValueError(
      'Invalid time format for a daily job (valid format is HH:MM(:SS)?)',
      514,
    );
  }

  const hours = Number(normalized.slice(0, 2));
  if (hours > 23) {
    throw new ScheduleValueError(
      'Invalid number of hours ({} is not between 0 and 23)',
      547,
    );
  }

  return normalized;
}
